import React, { useEffect, useState, useRef } from "react";
import { db } from "../js/firebase/firebaseConfig";
import {
    collection,
    addDoc,
    serverTimestamp,
    query,
    orderBy,
    onSnapshot,
    doc,
    setDoc,
    getDoc,
    updateDoc,
    where,
    getDocs,
    arrayUnion
} from "firebase/firestore";
import Avatar from "./Avatar";
import useSearchUsers from "../hooks/useSearchUsers";
import { uploadMessageMedia } from "../js/supabaseUpload";
import Picker from "emoji-picker-react";

function makeRoomId(a, b) {
    return [a, b].sort().join("_");
}

function formatTime(ts) {
    if (!ts) return "";
    const d = ts?.toDate ? ts.toDate() : new Date(ts);
    return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

/** extrai url de qualquer formato retornado pelo upload */
function getMessageUrl(m) {
    if (!m) return "";
    if (typeof m === "string") return m;
    if (typeof m === "object") {
        return m.publicUrl || m.publicURL || m.public_url || m.url || "";
    }
    return "";
}

export default function PrivateChat({ currentUser, otherUser, onClose }) {
    const roomId = makeRoomId(currentUser.uid, otherUser.id);
    const { allUsers } = useSearchUsers();

    const [messages, setMessages] = useState([]);
    const [text, setText] = useState("");

    const [file, setFile] = useState(null);
    const [previewUrl, setPreviewUrl] = useState("");

    const [uploading, setUploading] = useState(false);

    // edição
    const [editingMessage, setEditingMessage] = useState(null);
    const [editText, setEditText] = useState("");

    // emoji picker
    const [showEmoji, setShowEmoji] = useState(false);

    // gif url modal
    const [showGifModal, setShowGifModal] = useState(false);
    const [gifUrl, setGifUrl] = useState("");

    // menu flutuante mensagem
    const [openMenuId, setOpenMenuId] = useState(null);

    const listRef = useRef(null);
    const emojiContainerRef = useRef(null);

    useEffect(() => {
        let unsub;

        const setupChat = async () => {
            const roomRef = doc(db, "rooms", roomId);
            const snap = await getDoc(roomRef);

            if (!snap.exists()) {
                await setDoc(roomRef, {
                    members: [currentUser.uid, otherUser.id],
                    createdAt: serverTimestamp(),
                    lastMessage: "",
                    lastUpdated: serverTimestamp()
                });
            }

            const messagesRef = collection(db, `rooms/${roomId}/messages`);
            const q = query(messagesRef, orderBy("createdAt", "asc"));

            unsub = onSnapshot(q, async (s) => {
                const arr = s.docs.map(d => ({ id: d.id, ...d.data() }));
                setMessages(arr);

                // marcar recebidas (status)
                const updates = [];
                for (let d of s.docs) {
                    const data = d.data();
                    if (!data) continue;
                    if (data.from !== currentUser.uid && data.status === "sent") {
                        updates.push(updateDoc(d.ref, { status: "received" }));
                    }
                }
                if (updates.length) {
                    try { await Promise.all(updates); } catch (e) { /* ignore */ }
                }

                // scroll bottom
                setTimeout(() => {
                    if (listRef.current) listRef.current.scrollTop = listRef.current.scrollHeight;
                }, 40);
            });

            await markMessagesAsSeen();
        };

        setupChat();

        return () => {
            if (unsub) unsub();
        };
    }, [roomId, currentUser.uid, otherUser.id]);

    async function markMessagesAsSeen() {
        try {
            const messagesRef = collection(db, `rooms/${roomId}/messages`);
            const q = query(messagesRef, where("from", "!=", currentUser.uid));
            const snap = await getDocs(q);

            const updates = [];
            for (let d of snap.docs) {
                const data = d.data();
                if (!data) continue;
                const seenBy = data.seenBy || [];
                if (!seenBy.includes(currentUser.uid)) {
                    updates.push(updateDoc(d.ref, {
                        seenBy: arrayUnion(currentUser.uid),
                        status: "seen"
                    }));
                }
            }
            if (updates.length) await Promise.all(updates);
        } catch (err) {
            console.error("Erro marcando messages as seen:", err);
        }
    }

    /** Envia texto + mídia (se houver). Garante que o texto seja gravado junto da mídia */
    const send = async () => {
        const messageText = editingMessage ? editText.trim() : text.trim();
        if (!messageText && !file) return;

        setUploading(true);

        try {
            const textToSend = messageText;

            let url = "";
            let type = "text";

            if (file) {
                const res = await uploadMessageMedia(file, roomId);
                if (typeof res === "string") url = res;
                else url = res?.publicUrl || res?.publicURL || res?.public_url || res?.url || "";
                const lower = (file.type || "").toLowerCase();
                if (lower.startsWith("image/")) type = "image";
                else if (lower.startsWith("video/")) type = "video";
                else if (lower.startsWith("audio/")) type = "audio";
                else type = "file";
            }

            await addDoc(collection(db, `rooms/${roomId}/messages`), {
                text: textToSend || "",
                url: url || "",
                type,
                from: currentUser.uid,
                createdAt: serverTimestamp(),
                status: "sent",
                seenBy: []
            });

            await updateDoc(doc(db, "rooms", roomId), {
                lastMessage: textToSend || (type === "image" ? "[imagem]" :
                    type === "video" ? "[vídeo]" :
                        type === "audio" ? "[áudio]" : "[arquivo]"),
                lastUpdated: serverTimestamp()
            });

            // limpar
            setText("");
            setEditText("");
            setEditingMessage(null);

            if (file) {
                if (previewUrl) URL.revokeObjectURL(previewUrl);
                setFile(null);
                setPreviewUrl("");
            }
        } catch (err) {
            console.error("Erro ao enviar:", err);
            alert("Erro ao enviar mensagem: " + (err.message || err));
        } finally {
            setUploading(false);
        }
    };

    const onSelectFile = (e) => {
        const f = e.target.files[0];
        if (!f) return;
        const maxMB = 40;
        if (f.size > maxMB * 1024 * 1024) {
            return alert(`Arquivo muito grande (máx ${maxMB}MB).`);
        }
        setFile(f);
        try {
            const p = URL.createObjectURL(f);
            setPreviewUrl(p);
        } catch (err) {
            console.warn("Falha ao criar preview:", err);
            setPreviewUrl("");
        }
    };

    const startEditing = (msg) => {
        const created = msg.createdAt?.toDate?.()?.getTime?.() || (msg.createdAt ? new Date(msg.createdAt).getTime() : 0);
        if (Date.now() - created > 5 * 60 * 1000) return alert("Só pode editar mensagens até 5 minutos.");
        setEditingMessage(msg);
        setEditText(msg.text || "");
        setText(msg.text || "");
    };

    const saveEdit = async () => {
        if (!editingMessage) return;
        try {
            await updateDoc(doc(db, `rooms/${roomId}/messages`, editingMessage.id), {
                text: editText.trim(),
                edited: true,
                editedAt: serverTimestamp()
            });
            await updateDoc(doc(db, "rooms", roomId), {
                lastMessage: editText.trim() || "",
                lastUpdated: serverTimestamp()
            });
            setEditingMessage(null);
            setEditText("");
            setText("");
        } catch (err) {
            console.error("Erro salvando edição:", err);
            alert("Erro ao editar: " + (err.message || err));
        }
    };

    const cancelEdit = () => {
        setEditingMessage(null);
        setEditText("");
        setText("");
    };

    const deleteForMe = async (msg) => {
        try {
            await updateDoc(doc(db, `rooms/${roomId}/messages`, msg.id), {
                deletedFor: arrayUnion(currentUser.uid)
            });
        } catch (err) {
            console.error(err);
            alert("Erro ao excluir para mim.");
        }
    };

    const deleteForAll = async (msg) => {
        try {
            const seen = msg.seenBy || [];
            if (seen.length > 0) return alert("Não é possível excluir para todos: mensagem já foi vista.");
            await updateDoc(doc(db, `rooms/${roomId}/messages`, msg.id), {
                deletedForAll: true,
                text: "",
                url: "",
                type: "text",
                edited: false,
                deletedAt: serverTimestamp()
            });
        } catch (err) {
            console.error(err);
            alert("Erro ao excluir para todos: " + (err.message || err));
        }
    };

    const renderStatus = (m) => {
        if (m.from !== currentUser.uid) return null;
        if (m.deletedForAll) return null;
        const st = m.status || "sent";
        if (st === "sent") return <span>✓</span>;
        if (st === "received") return <span>✓✓</span>;
        if (st === "seen") return <span style={{ color: "#1ca3ff" }}>✓✓</span>;
        return null;
    };

    const findUserById = (id) => allUsers?.find(u => u.id === id);

    // Menu de 3 pontos (para mensagens próprias)
    const MessageMenu = ({ msg }) => {
        if (msg.from !== currentUser.uid) return null;
        return (
            <div style={{ position: "absolute", top: -4, right: -4, zIndex: 40 }}>
                <button onClick={() => setOpenMenuId(openMenuId === msg.id ? null : msg.id)} style={{ background: "transparent", border: "none", cursor: "pointer" }}>⋮</button>
                {openMenuId === msg.id && (
                    <div style={{
                        position: "absolute",
                        right: 0,
                        top: 22,
                        background: "#fff",
                        border: "1px solid #ddd",
                        borderRadius: 8,
                        boxShadow: "0 2px 6px rgba(0,0,0,0.12)",
                        width: 140
                    }}>
                        <div style={{ padding: 10, cursor: "pointer" }} onClick={() => { setOpenMenuId(null); startEditing(msg); }}>Editar</div>
                        <div style={{ padding: 10, cursor: "pointer" }} onClick={() => { setOpenMenuId(null); deleteForMe(msg); }}>Excluir para mim</div>
                        <div style={{ padding: 10, cursor: "pointer" }} onClick={() => { setOpenMenuId(null); deleteForAll(msg); }}>Excluir para todos</div>
                    </div>
                )}
            </div>
        );
    };

    // emoji click handler (garante pegar .emoji)
    const handleEmojiClick = (emojiObject) => {
        const emoji = emojiObject?.emoji || "";
        if (!emoji) return;
        if (editingMessage) setEditText(prev => prev + emoji);
        else setText(prev => prev + emoji);
    };

    return (
        <>
            {/* header */}
            <div className="chat-header">
                <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <button onClick={onClose} style={{ background: "transparent", border: "none", color: "#fff", fontSize: 18 }}>←</button>
                    <Avatar user={otherUser} size={44} />
                    <div>
                        <div style={{ fontWeight: 700 }}>{otherUser.nome || otherUser.email}</div>
                        <div style={{ fontSize: 12 }}>{otherUser.email}</div>
                    </div>
                </div>
            </div>

            {/* messages */}
            <div className="chat-box" ref={listRef} style={{ overflowY: "auto" }}>
                {messages.map(m => {
                    if (m.deletedFor?.includes(currentUser.uid)) return null;

                    const isMe = m.from === currentUser.uid;
                    const sender = findUserById(m.from) || otherUser;

                    // mensagem excluída para todos: mostrar bolha alinhada ao remetente
                    if (m.deletedForAll) {
                        return (
                            <div
                                key={m.id}
                                style={{
                                    display: "flex",
                                    justifyContent: isMe ? "flex-end" : "flex-start",
                                    marginBottom: 10
                                }}
                            >
                                <div className={`msg ${isMe ? "me" : "other"}`} style={{ maxWidth: 320 }}>
                                    <div style={{ fontStyle: "italic", color: "#666" }}>Mensagem excluída</div>
                                    <div className="hora" style={{ textAlign: isMe ? "right" : "left", marginTop: 6 }}>{formatTime(m.createdAt)}</div>
                                </div>
                            </div>
                        );
                    }

                    const msgUrl = getMessageUrl(m.url);

                    return (
                        <div
                            key={m.id}
                            style={{
                                display: "flex",
                                justifyContent: isMe ? "flex-end" : "flex-start",
                                marginBottom: 10,
                                position: "relative"
                            }}
                        >
                            {!isMe && <div style={{ marginRight: 8 }}><Avatar user={sender} size={36} /></div>}

                            <div className={`msg ${isMe ? "me" : "other"}`} style={{ maxWidth: 320, position: "relative" }}>
                                {isMe && <MessageMenu msg={m} />}

                                {/* Conteúdo multimídia + texto abaixo (se houver) */}
                                {m.type === "image" && msgUrl && (
                                    <>
                                        <img src={msgUrl} alt="img" style={{ maxWidth: "100%", maxHeight: 360, borderRadius: 8 }} />
                                        {m.text ? <div style={{ marginTop: 8, whiteSpace: "pre-wrap" }}>{m.text}</div> : null}
                                    </>
                                )}

                                {m.type === "video" && msgUrl && (
                                    <>
                                        <video src={msgUrl} controls style={{ maxWidth: "100%", maxHeight: 360, borderRadius: 8 }} />
                                        {m.text ? <div style={{ marginTop: 8, whiteSpace: "pre-wrap" }}>{m.text}</div> : null}
                                    </>
                                )}

                                {m.type === "audio" && msgUrl && (
                                    <>
                                        <audio src={msgUrl} controls />
                                        {m.text ? <div style={{ marginTop: 8, whiteSpace: "pre-wrap" }}>{m.text}</div> : null}
                                    </>
                                )}

                                {m.type === "gif" && msgUrl && (
                                    <>
                                        <img src={msgUrl} alt="gif" style={{ maxWidth: "100%", borderRadius: 8 }} />
                                        {m.text ? <div style={{ marginTop: 8, whiteSpace: "pre-wrap" }}>{m.text}</div> : null}
                                    </>
                                )}

                                {m.type === "file" && msgUrl && (
                                    <>
                                        <a href={msgUrl} target="_blank" rel="noreferrer">{msgUrl.split("/").pop()}</a>
                                        {m.text ? <div style={{ marginTop: 8, whiteSpace: "pre-wrap" }}>{m.text}</div> : null}
                                    </>
                                )}

                                {/* texto puro */}
                                {(m.type === "text" || (!m.type && m.text)) && (
                                    <div style={{ whiteSpace: "pre-wrap" }}>{m.text}</div>
                                )}

                                {/* editado */}
                                {m.edited && <div style={{ fontSize: 11, opacity: 0.6, marginTop: 6 }}>(editada)</div>}

                                {/* hora + status */}
                                <div className="hora" style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 6 }}>
                                    <div style={{ fontSize: 11 }}>{formatTime(m.createdAt)}</div>
                                    {renderStatus(m)}
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* input area */}
            <div className="chat-input" style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {/* preview */}
                {previewUrl && (
                    <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
                        {file && file.type.startsWith("image/") && <img src={previewUrl} alt="prev" style={{ width: 120, height: 80, objectFit: "cover", borderRadius: 8 }} />}
                        {file && file.type.startsWith("video/") && <video src={previewUrl} style={{ width: 140 }} controls />}
                        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                            <div style={{ fontSize: 13, fontWeight: 700 }}>{file?.name}</div>
                            <button onClick={() => { if (previewUrl) URL.revokeObjectURL(previewUrl); setPreviewUrl(""); setFile(null); }}>Remover</button>
                        </div>
                    </div>
                )}

                {/* GIF modal */}
                {showGifModal && (
                    <div style={{ padding: 10, border: "1px solid #ccc", borderRadius: 8 }}>
                        <input value={gifUrl} onChange={e => setGifUrl(e.target.value)} placeholder="Cole URL do GIF" style={{ width: "75%" }} />
                        <button onClick={() => setShowGifModal(false)}>Fechar</button>
                        <button onClick={() => {
                            if (!gifUrl) return alert("Cole a URL");
                            setFile(null);
                            setPreviewUrl("");
                            (async () => {
                                try {
                                    await addDoc(collection(db, `rooms/${roomId}/messages`), {
                                        text: "",
                                        url: gifUrl,
                                        type: "gif",
                                        from: currentUser.uid,
                                        createdAt: serverTimestamp(),
                                        status: "sent",
                                        seenBy: []
                                    });
                                    await updateDoc(doc(db, "rooms", roomId), { lastMessage: "[gif]", lastUpdated: serverTimestamp() });
                                    setShowGifModal(false);
                                    setGifUrl("");
                                } catch (err) {
                                    alert("Erro ao enviar GIF: " + err.message);
                                }
                            })();
                        }}>Enviar GIF</button>
                    </div>
                )}

                <div style={{ display: "flex", gap: 8, alignItems: "center", position: "relative" }}>
                    {/* emoji container relativo: picker ficará acima do botão */}
                    <div ref={emojiContainerRef} style={{ position: "relative", display: "inline-block" }}>
                        <button onClick={() => setShowEmoji(v => !v)} style={{ padding: 8, borderRadius: 8 }}>😊</button>

                        {showEmoji && (
                            <div style={{
                                position: "absolute",
                                bottom: 56,
                                left: 0,
                                zIndex: 120,
                                boxShadow: "0 6px 18px rgba(0,0,0,0.15)"
                            }}>
                                {/* picker: versoes diferentes têm assinatura diferente; pegamos o emojiObject */}
                                <Picker onEmojiClick={(event, emojiObject) => handleEmojiClick(emojiObject)} />
                            </div>
                        )}
                    </div>

                    <input
                        value={editingMessage ? editText : text}
                        onChange={e => {
                            if (editingMessage) setEditText(e.target.value);
                            else setText(e.target.value);
                        }}
                        placeholder={editingMessage ? "Editando..." : "Mensagem..."}
                        style={{ flex: 1, padding: 12, borderRadius: 25, border: "1px solid #ccc" }}
                    />

                    <label style={{ cursor: "pointer" }}>
                        📎
                        <input type="file" style={{ display: "none" }} accept="image/*,video/*,audio/*,*/*" onChange={onSelectFile} />
                    </label>

                    <button onClick={() => setShowGifModal(v => !v)} style={{ padding: 8, borderRadius: 8 }}>GIF</button>

                    {editingMessage ? (
                        <>
                            <button onClick={cancelEdit}>Cancelar</button>
                            <button onClick={saveEdit} style={{ background: "#075E54", color: "#fff", borderRadius: 8 }}>Salvar</button>
                        </>
                    ) : (
                        <button onClick={send} disabled={uploading} style={{ background: "#075E54", color: "#fff", borderRadius: 20, padding: "8px 12px" }}>
                            {uploading ? "Enviando..." : "Enviar"}
                        </button>
                    )}
                </div>
            </div>
        </>
    );
}
